// ../../packages/server/browser.ts
var { $ } = globalThis.Bun
import os from "os"
async function isWSL() {
  if (process.platform !== "linux") {
    return false
  }
  if (os.release().toLowerCase().includes("microsoft")) {
    return true
  }
  try {
    const file = Bun.file("/proc/version")
    if (await file.exists()) {
      const content = await file.text()
      return content.toLowerCase().includes("wsl") || content.toLowerCase().includes("microsoft")
    }
  } catch {}
  return false
}
async function openBrowser(url) {
  try {
    const platform = process.platform
    const wsl = await isWSL()
    if (platform === "win32" || wsl) {
      await $`cmd.exe /c start ${url}`.quiet()
    } else if (platform === "darwin") {
      await $`open ${url}`.quiet()
    } else {
      await $`xdg-open ${url}`.quiet()
    }
    return true
  } catch {
    return false
  }
}

// ../../packages/server/lib/reference-file.ts
import path from "path"
import fs from "fs"

// ../../packages/util/src/encode.ts
function base64Encode(value) {
  const bytes = new TextEncoder().encode(value)
  const binary = Array.from(bytes, (b) => String.fromCharCode(b)).join("")
  return btoa(binary).replace(/\+/g, "-").replace(/\//g, "_").replace(/=/g, "")
}
function base64Decode(value) {
  const binary = atob(value.replace(/-/g, "+").replace(/_/g, "/"))
  const bytes = Uint8Array.from(binary, (c) => c.charCodeAt(0))
  return new TextDecoder().decode(bytes)
}

// ../../packages/server/lib/headers.ts
var CORS_HEADERS = {
  "Access-Control-Allow-Origin": "*",
  "Access-Control-Allow-Methods": "GET, POST, OPTIONS, DELETE",
  "Access-Control-Allow-Headers": "Content-Type",
}

// ../../packages/server/lib/reference-file.ts
var getDirectory = (directory) => {
  return path.join(base64Decode(directory), "__reference")
}
var getReferenceFiles = async (directory) => {
  try {
    if (!directory) {
      return { error: "Directory is required" }
    }
    const referencePath = getDirectory(directory)
    const files = (fs.readdirSync(referencePath) || [])
      .sort((a, b) => {
        return (
          fs.statSync(path.join(referencePath, b)).mtime.getTime() -
          fs.statSync(path.join(referencePath, a)).mtime.getTime()
        )
      })
      .map((file) => {
        const stats = fs.statSync(path.join(referencePath, file))
        return {
          name: file,
          size: stats.size,
          createdAt: stats.mtime.getTime(),
        }
      })
    return { files }
  } catch (error) {
    return { files: [] }
  }
}
var getReferenceFileRoutes = () => {
  return {
    "/api/reference-files/:directory": {
      GET: async (request) => {
        const directory = request.params.directory
        if (!directory) {
          return Response.json({ error: "Directory is required" }, { status: 400, headers: CORS_HEADERS })
        }
        const files = await getReferenceFiles(directory)
        return Response.json(files, { headers: CORS_HEADERS })
      },
    },
    "/api/reference-files/upload": {
      POST: async (request) => {
        try {
          const url = new URL(request.url)
          const directory = url.searchParams.get("directory")
          if (!directory) {
            return Response.json({ error: "Directory is required" }, { status: 400, headers: CORS_HEADERS })
          }
          const formData = await request.formData()
          const files = formData.getAll("files")
          if (!files || files.length === 0) {
            return Response.json({ error: "No files found" }, { status: 400, headers: CORS_HEADERS })
          }
          const referencePath = getDirectory(directory)
          if (!fs.existsSync(referencePath)) {
            fs.mkdirSync(referencePath, { recursive: true })
          }
          for (const file of files) {
            if (file instanceof File) {
              const arrayBuffer = await file.arrayBuffer()
              const filePath = path.join(referencePath, file.name)
              fs.writeFileSync(filePath, Buffer.from(arrayBuffer))
            }
          }
          return Response.json(true, { headers: CORS_HEADERS })
        } catch (error) {
          console.error("Upload Error:", error)
          return Response.json({ error: error.message }, { status: 500, headers: CORS_HEADERS })
        }
      },
    },
    "/api/reference-files/remove-file": {
      DELETE: async (request) => {
        try {
          const url = new URL(request.url)
          const directory = url.searchParams.get("directory")
          if (!directory) {
            return Response.json({ error: "Directory is required" }, { status: 400, headers: CORS_HEADERS })
          }
          const name = url.searchParams.get("name")
          if (!name) {
            return Response.json({ error: "Name is required" }, { status: 400, headers: CORS_HEADERS })
          }
          const referencePath = getDirectory(directory)
          const filePath = path.join(referencePath, name)
          if (!fs.existsSync(filePath)) {
            return Response.json({ error: "File not found" }, { status: 404, headers: CORS_HEADERS })
          }
          fs.unlinkSync(filePath)
          return Response.json(true, { headers: CORS_HEADERS })
        } catch (error) {
          console.error("Remove File Error:", error)
          return Response.json({ error: error.message }, { status: 500, headers: CORS_HEADERS })
        }
      },
    },
  }
}

// ../../packages/server/lib/routes.ts
var getRoutes = () => {
  return {
    ...getReferenceFileRoutes(),
  }
}

// ../../packages/server/index.ts
var MAX_RETRIES = 5
var RETRY_DELAY_MS = 500
var SERVER_PORT = 40960
async function startServer(options) {
  const { origin, htmlContent, onReady } = options
  const configuredPort = SERVER_PORT
  let resolveDecision
  const decisionPromise = new Promise((resolve) => {
    resolveDecision = resolve
  })
  let server = null
  for (let attempt = 1; attempt <= MAX_RETRIES; attempt++) {
    try {
      server = Bun.serve({
        port: configuredPort,
        routes: getRoutes(),
        async fetch(req) {
          if (req.method === "OPTIONS") {
            return new Response(null, { headers: CORS_HEADERS })
          }
          const url = new URL(req.url)
          if (url.pathname === "/api/image") {
            const imagePath = url.searchParams.get("path")
            if (!imagePath) {
              return new Response("Missing path parameter", { status: 400 })
            }
            try {
              const file = Bun.file(imagePath)
              if (!(await file.exists())) {
                return new Response("File not found", { status: 404 })
              }
              return new Response(file)
            } catch {
              return new Response("Failed to read file", { status: 500 })
            }
          }
          if (url.pathname === "/api/upload" && req.method === "POST") {
            try {
              const formData = await req.formData()
              const file = formData.get("file")
              if (!file) {
                return new Response("No file provided", { status: 400 })
              }
              const ext = file.name.split(".").pop() || "png"
              const tempDir = "/tmp/plannotator"
              mkdirSync(tempDir, { recursive: true })
              const tempPath = `${tempDir}/${crypto.randomUUID()}.${ext}`
              await Bun.write(tempPath, file)
              return Response.json({ path: tempPath })
            } catch (err) {
              const message = err instanceof Error ? err.message : "Upload failed"
              return Response.json({ error: message }, { status: 500 })
            }
          }
          return new Response(htmlContent, {
            headers: { "Content-Type": "text/html" },
          })
        },
      })
      break
    } catch (err) {
      const isAddressInUse = err instanceof Error && err.message.includes("EADDRINUSE")
      if (isAddressInUse && attempt < MAX_RETRIES) {
        await Bun.sleep(RETRY_DELAY_MS)
        continue
      }
      if (isAddressInUse) {
        throw new Error(`Port ${configuredPort} in use after ${MAX_RETRIES} retries`)
      }
      throw err
    }
  }
  if (!server) {
    throw new Error("Failed to start server")
  }
  const serverUrl = `http://localhost:${server.port}`
  if (onReady) {
    onReady(serverUrl, server.port)
  }
  return {
    port: server.port,
    url: serverUrl,
    waitForDecision: () => decisionPromise,
    stop: () => server.stop(),
  }
}

