// load-commands.ts
var __dirname = "/Users/Zhuanz/Documents/workspace/opencode-plugins/apps/reference-files"
function parseFrontmatter(content) {
  const frontmatterRegex = /^---\n([\s\S]*?)\n---\n([\s\S]*)$/
  const match = content.match(frontmatterRegex)
  if (!match) {
    return { frontmatter: {}, body: content.trim() }
  }
  const [, yamlContent, body] = match
  const frontmatter = {}
  for (const line of yamlContent?.split(`
`) ?? []) {
    const colonIndex = line.indexOf(":")
    if (colonIndex === -1) continue
    const key = line.slice(0, colonIndex).trim()
    const value = line.slice(colonIndex + 1).trim()
    if (key === "description") frontmatter.description = value
    if (key === "agent") frontmatter.agent = value
    if (key === "model") frontmatter.model = value
    if (key === "subtask") frontmatter.subtask = value === "true"
  }
  return { frontmatter, body: body?.trim() ?? "" }
}
var getCommandContent = () => {
  const { frontmatter, body } = parseFrontmatter(reference_files_default)
  return {
    template: body,
    name: "reference-files",
    frontmatter,
  }
}

