var ReferenceFilesPlugin = async ({ project, client, $: $2, directory, worktree }) => {
  return {
    event: async ({ event }) => {
      const isCommandEvent = event.type === "command.executed" || event.type === "tui.command.execute"
      const commandName = event.properties?.name || event.command || event.payload?.name
      const isFileCommand = commandName === "reference-files"
      if (isCommandEvent && isFileCommand) {
        const server = await startServer({
          origin: "opencode",
          htmlContent: reference_files_default2,
          onReady: (url) => {
            openBrowser(url + "?d=" + base64Encode(directory))
          },
        })
        const result = await server.waitForDecision()
        await Bun.sleep(1500)
        server.stop()
      }
    },
    async config(config) {
      config.command = config.command ?? {}
      const commandContent = getCommandContent()
      const { frontmatter, template } = commandContent
      config.command[commandContent.name] = {
        template,
        description: frontmatter?.description,
        agent: frontmatter?.agent,
        model: frontmatter?.model,
        subtask: frontmatter?.subtask,
      }
    },
  }
}
export { ReferenceFilesPlugin }
